using MunicipalPlatform.Api.Platform.Tenancy;
namespace MunicipalPlatform.Api.Modules.Migration.Domain;

public sealed class MigrationEvidence : ITenantEntity { private MigrationEvidence() { } public MigrationEvidence(Guid municipalityId, Guid migrationJobId, string kind, string reference, string payloadJson) { Id = Guid.NewGuid(); MunicipalityId = municipalityId; MigrationJobId = migrationJobId; Kind = kind.Trim(); Reference = reference.Trim(); PayloadJson = payloadJson; CreatedAt = DateTimeOffset.UtcNow; } public Guid Id { get; private set; } public Guid MunicipalityId { get; private set; } public Guid MigrationJobId { get; private set; } public string Kind { get; private set; } = string.Empty; public string Reference { get; private set; } = string.Empty; public string PayloadJson { get; private set; } = "{}"; public DateTimeOffset CreatedAt { get; private set; } }
